import sys
from collections import defaultdict, deque

# Read input
n = int(sys.stdin.readline().strip())
roads = list(map(int, sys.stdin.readline().strip().split()))
m = int(sys.stdin.readline().strip())
bus_routes = [list(map(int, sys.stdin.readline().strip().split())) for _ in range(m)]
q = int(sys.stdin.readline().strip())
questions = [list(map(int, sys.stdin.readline().strip().split())) for _ in range(q)]

# Build the graph
graph = defaultdict(list)
for i in range(2, n + 1):
    graph[roads[i - 2]].append(i)
    graph[i].append(roads[i - 2])

# Precompute the shortest path for each bus route
shortest_path = {}
for a, b in bus_routes:
    if a > b:
        a, b = b, a
    if (a, b) not in shortest_path:
        queue = deque([(a, 0)])
        visited = set([a])
        while queue:
            node, dist = queue.popleft()
            if node == b:
                shortest_path[(a, b)] = dist
                break
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))

# Process each question
for v, u in questions:
    if v > u:
        v, u = u, v
    if (v, u) in shortest_path:
        print(shortest_path[(v, u)])
    else:
        print(-1)
